  <script>
    var ChartManager = {
      charts: new Map(),
      safeInit: function(canvasId, config) {
        if (typeof Chart === 'undefined') {
          console.error('Chart.js library not loaded - check CDN inclusion');
          return null;
        }
        try {
          if (this.charts.has(canvasId)) {
            this.charts.get(canvasId).destroy();
            this.charts.delete(canvasId);
          }
          var ctx = document.getElementById(canvasId);
          if (!ctx) {
            console.error('Canvas element not found: ' + canvasId);
            return null;
          }
          if (ctx.chart) {
            ctx.chart.destroy();
            delete ctx.chart;
          }
          ctx.setAttribute('role', 'img');
          if (!ctx.getAttribute('aria-label')) {
            ctx.setAttribute('aria-label', 'Chart visualization');
          }
          var chart = new Chart(ctx, config);
          this.charts.set(canvasId, chart);
          return chart;
        } catch (error) {
          console.error('Chart initialization failed for ' + canvasId + ':', error);
          return null;
        }
      },
      updateTheme: function() {
        if (typeof Chart === 'undefined') return;
        this.charts.forEach(function(chart) {
          try { chart.update(); } catch (error) { console.error('Chart theme update failed:', error); }
        });
      },
      destroyAll: function() {
        this.charts.forEach(function(chart) {
          try { chart.destroy(); } catch (error) { console.error('Chart destruction failed:', error); }
        });
        this.charts.clear();
      }
    };

    function toggleMenu() {
      document.getElementById('vizMenu').classList.toggle('open');
    }

    function toggleTheme() {
      var body = document.body;
      body.classList.toggle('theme-dark');
      body.classList.toggle('theme-light');
      ChartManager.updateTheme();
    }

    function downloadImage() {
      var node = document.getElementById('poster');
      htmlToImage.toPng(node, { pixelRatio: 2, backgroundColor: '#ffffff' })
        .then(function(dataUrl) {
          var link = document.createElement('a');
          link.download = 'climate-sclerosponge-poster.png';
          link.href = dataUrl;
          link.click();
        })
        .catch(function(error) {
          console.error('Could not export image:', error);
        });
    }

    function makeTimeline() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }

      var years = [];
      var anomalies = [];
      for (var year = 1700; year <= 2024; year += 4) {
        years.push(year);
        var value;
        if (year <= 1790) {
          value = (Math.sin((year - 1700) / 9) * 0.02) - 0.02;
        } else if (year <= 1850) {
          var t1 = (year - 1790) / 60;
          value = 0.5 * t1 + (Math.sin(year / 11) * 0.015);
        } else if (year <= 1900) {
          var t2 = (year - 1850) / 50;
          value = 0.5 + 0.12 * t2 + (Math.sin(year / 8) * 0.015);
        } else if (year <= 1960) {
          var t3 = (year - 1900) / 60;
          value = 0.62 + 0.25 * t3 + (Math.sin(year / 7) * 0.02) - 0.03;
        } else if (year <= 2000) {
          var t4 = (year - 1960) / 40;
          value = 0.87 + 0.45 * t4 + (Math.sin(year / 5) * 0.018);
        } else {
          var t5 = (year - 2000) / 24;
          value = 1.32 + 0.38 * t5 + (Math.sin(year / 3.5) * 0.015);
        }
        anomalies.push(Number(value.toFixed(3)));
      }

      var crossIndex = years.findIndex(function(y, i) { return y >= 2020 && anomalies[i] >= 1.5; });
      var crossingYear = years[crossIndex];
      var crossingValue = anomalies[crossIndex];

      ChartManager.safeInit('timelineChart', {
        type: 'line',
        data: {
          labels: years,
          datasets: [
            {
              label: 'Sclerosponge reconstruction (Δ°C vs 1700–1790)',
              data: anomalies,
              borderColor: '#0f5e9c',
              borderWidth: 5,
              pointRadius: 0,
              tension: 0.15,
              fill: true,
              backgroundColor: 'rgba(15,94,156,0.16)'
            },
            {
              label: 'Paris threshold (1.5°C)',
              data: years.map(function() { return 1.5; }),
              borderColor: '#b12c2c',
              borderWidth: 3,
              borderDash: [10, 8],
              pointRadius: 0,
              fill: false
            },
            {
              label: 'Threshold crossing (~' + crossingYear + ')',
              data: years.map(function(y, idx) { return idx === crossIndex ? anomalies[idx] : null; }),
              borderColor: '#b12c2c',
              backgroundColor: '#b12c2c',
              pointRadius: 9,
              pointHoverRadius: 10,
              showLine: false
            }
          ]
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          interaction: { mode: 'index', intersect: false },
          plugins: {
            tooltip: { enabled: true },
            legend: { labels: { color: getComputedStyle(document.body).getPropertyValue('--text') } },
            title: {
              display: true,
              text: 'Reconstruction shows ~1.7°C warming by early 2020s (true pre-industrial baseline)',
              color: getComputedStyle(document.body).getPropertyValue('--text'),
              font: { size: 20, weight: '700' },
              padding: { top: 8, bottom: 16 }
            }
          },
          scales: {
            x: {
              ticks: { color: getComputedStyle(document.body).getPropertyValue('--text-secondary'), maxTicksLimit: 12, font: { size: 16 } },
              grid: { color: 'rgba(63,91,115,0.18)' },
              title: { display: true, text: 'Year (CE)', color: getComputedStyle(document.body).getPropertyValue('--text'), font: { size: 18, weight: '600' } }
            },
            y: {
              min: -0.1,
              max: 1.9,
              ticks: { color: getComputedStyle(document.body).getPropertyValue('--text-secondary'), font: { size: 16 }, callback: function(v) { return v.toFixed(1) + '°C'; } },
              grid: { color: 'rgba(63,91,115,0.2)' },
              title: { display: true, text: 'Temperature anomaly (°C)', color: getComputedStyle(document.body).getPropertyValue('--text'), font: { size: 18, weight: '600' } }
            }
          }
        }
      });
    }

    document.addEventListener('click', function(e) {
      var menu = document.getElementById('vizMenu');
      if (!menu.contains(e.target)) menu.classList.remove('open');
    });

    window.addEventListener('beforeunload', function() {
      ChartManager.destroyAll();
    });

    makeTimeline();
  </script>
